    gradientLength: Optional[Union[confloat(ge=0.0), ExprRef]] = None
    gradientOpacity: Optional[Union[float, ExprRef]] = None
    gradientStrokeColor: Optional[Union[Optional[Color], ExprRef]] = None
    gradientStrokeWidth: Optional[Union[confloat(ge=0.0), ExprRef]] = None
