    clipAngle: Optional[Union[float, ExprRef]] = None
    clipExtent: Optional[Union[Vector2Vector2Number, ExprRef]] = None
    coefficient: Optional[Union[float, ExprRef]] = None
    distance: Optional[Union[float, ExprRef]] = None
    extent: Optional[Union[Vector2Vector2Number, ExprRef]] = None
    fit: Optional[Union[Fit, List[Fit], ExprRef]] = None
    fraction: Optional[Union[float, ExprRef]] = None
    lobes: Optional[Union[float, ExprRef]] = None
    parallel: Optional[Union[float, ExprRef]] = None
    parallels: Optional[Union[List[float], ExprRef]] = None
    pointRadius: Optional[Union[float, ExprRef]] = None
    precision: Optional[Union[float, ExprRef]] = None
    radius: Optional[Union[float, ExprRef]] = None
    ratio: Optional[Union[float, ExprRef]] = None
    reflectX: Optional[Union[bool, ExprRef]] = None
    reflectY: Optional[Union[bool, ExprRef]] = None
    rotate: Optional[Union[Union[Vector2Number, Vector3Number], ExprRef]] = None
    scale: Optional[Union[float, ExprRef]] = None
    """
    The projection’s scale (zoom) factor, overriding automatic fitting. The default scale is projection-specific. The scale factor corresponds linearly to the distance between projected points; however, scale factor values are not equivalent across projections.
    """
    size: Optional[Union[Vector2Number, ExprRef]] = None
    spacing: Optional[Union[float, ExprRef]] = None
    tilt: Optional[Union[float, ExprRef]] = None
    translate: Optional[Union[Vector2Number, ExprRef]] = None
